CREATE OR REPLACE FUNCTION public.wake_submit_answer(_event_id uuid, _version integer, _answer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE u uuid:=auth.uid(); e public.alarm_events; a public.alarms; correct boolean; needed integer; awarded integer:=0; result text; day date; inserted boolean; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE='42501'; END IF; IF length(_answer)>40 THEN RAISE EXCEPTION 'invalid answer'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74010)); PERFORM pg_advisory_xact_lock(hashtextextended(u::text,74011)); SELECT * INTO e FROM public.alarm_events WHERE id=_event_id AND user_id=u FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'alarm not found' USING ERRCODE='42501'; END IF; IF e.status='solved' THEN RETURN jsonb_build_object('solved',true,'correct',true,'awarded',0,'result','daily_claimed','event',public.wake_event_payload(e.id)); END IF; IF e.status<>'ringing' OR e.question_version<>_version THEN RAISE EXCEPTION 'Challenge changed. Reload the current question.'; END IF; IF e.last_answer_at>now()-interval '400 milliseconds' THEN RAISE EXCEPTION 'Please wait before another answer'; END IF; correct:=CASE WHEN e.question_type='science' THEN trim(_answer)=e.question_answer WHEN trim(_answer)~'^-?[0-9]+(\.[0-9]+)?$' THEN trim(_answer)::numeric=e.question_answer::numeric ELSE false END; needed:=CASE WHEN e.question_type='science' THEN 2 ELSE 1 END; UPDATE public.alarm_events SET correct_in_row=CASE WHEN correct THEN correct_in_row+1 ELSE 0 END,last_answer_at=now() WHERE id=e.id; IF NOT correct OR e.correct_in_row+1<needed THEN PERFORM public.wake_issue_question(e.id); RETURN jsonb_build_object('solved',false,'correct',correct,'explanation',CASE WHEN correct THEN e.question_explanation ELSE NULL END,'event',public.wake_event_payload(e.id)); END IF; UPDATE public.alarm_events SET status='solved',solved_at=now(),next_push_at=NULL WHERE id=e.id; result:=CASE WHEN e.is_test THEN 'test_alarm' WHEN e.tier=0 THEN 'outside_reward_window' WHEN e.first_ring_at-e.saved_at<interval '2 hours' THEN 'saved_too_late' WHEN now()-e.first_ring_at>interval '30 minutes' THEN 'solve_too_late' ELSE 'eligible' END; IF result='eligible' THEN awarded:=public.axen_award_completion_coins(u,'wake',e.id); result:=CASE WHEN awarded>0 THEN 'awarded' ELSE 'daily_claimed' END; END IF; SELECT * INTO a FROM public.alarms WHERE id=e.alarm_id FOR UPDATE; day:=public.axen_reward_local_day(u); IF NOT e.is_test THEN PERFORM set_config('app.economy_write','on',true); PERFORM set_config('axen.contract_write','on',true); INSERT INTO public.alarm_sessions(user_id,alarm_id,completed_on,coins_awarded,status,checked_in_at) VALUES(u,a.id,day,awarded,'completed',now()) ON CONFLICT(user_id,alarm_id,completed_on) DO NOTHING; inserted:=FOUND; IF inserted THEN UPDATE public.profiles SET streak=CASE WHEN last_activity_date=day THEN streak WHEN last_activity_date=day-1 THEN streak+1 ELSE 1 END,longest_streak=greatest(longest_streak,CASE WHEN last_activity_date=day THEN streak WHEN last_activity_date=day-1 THEN streak+1 ELSE 1 END),last_activity_date=day WHERE id=u; IF public.wake_slot_reward((extract(hour FROM e.wake_time))::integer::text||'AM')>0 THEN INSERT INTO public.score_events(user_id,points,kind,idempotency_key) VALUES(u,public.wake_slot_reward((extract(hour FROM e.wake_time))::integer::text||'AM'),'wake_verified','wake:'||u::text||':'||day::text) ON CONFLICT(idempotency_key) DO NOTHING; END IF; INSERT INTO public.task_completions(user_id,task_id,completed_on,coins_awarded) SELECT u,id,day,0 FROM public.tasks WHERE user_id=u AND is_active AND name~*'wake' ON CONFLICT(user_id,task_id,completed_on) DO NOTHING; END IF; IF a.wake_repeat_daily AND a.is_active THEN UPDATE public.alarms SET wake_next_fire_at=public.wake_next_fire(a.time,a.wake_timezone) WHERE id=a.id; PERFORM public.wake_create_occurrence(a.id); ELSE UPDATE public.alarms SET wake_next_fire_at=NULL,is_active=false WHERE id=a.id; END IF; END IF; UPDATE public.alarm_events SET coins_awarded=awarded,reward_result=result WHERE id=e.id; UPDATE public.wake_push_outbox SET status='cancelled' WHERE event_id=e.id AND status IN ('pending','leased'); INSERT INTO public.wake_delivery_log(event_id,kind) VALUES(e.id,'solved'); RETURN jsonb_build_object('solved',true,'correct',true,'awarded',awarded,'result',result,'explanation',e.question_explanation,'event',public.wake_event_payload(e.id)); END; $function$;